return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Swahili','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-01 20:14+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'sw','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['Lingua Forge'=>'Lingua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Usanifu wa lugha nyingi, alama za meta za SEO, na zana za maudhui za AI kwa WordPress. Inachanganya utambuzi wa lugha, usafirishaji wa URL, hreflang, maelezo ya meta, na sifa za kukata, meta, na tafsiri zinazotumiwa na AI.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Tafsiri','Lingua Forge — Quick Translate'=>'Lingua Forge — Tafsiri Haraka','Informative'=>'Taarifa','Persuasive'=>'Ushawishi','Storytelling'=>'Hadithi','Technical'=>'Kitaaluma','Conversational'=>' Mazungumzo','Permission denied.'=>'Ruhusa imekatwa.','Cannot determine target language from slug.'=>'Haiwezi kubaini lugha lengwa kutoka kwa slug.','Invalid post type.'=>'Aina ya chapisho si sahihi.','Invalid or primary language.'=>'Lugha si sahihi au ni kuu.','Template not found or not stored in the database.'=>'Kiolezo hakipatikani au hakijahifadhiwa kwenye hifadhidata.','Template has no content.'=>'Kiolezo hakina maudhui.','No internal links found to update.'=>'Hakuna viungo vya ndani vilivyopatikana vya kusasisha.','%d link updated.'=>'%d kiungo kimesasishwa.' . "\0" . '%d viungo vimesasishwa.','No language-specific template parts found to map.'=>'Hakuna sehemu za kiolezo zinazohitajika kubadilishwa ili kuoanisha.','No template part references needed updating.'=>'Hakuna marejeo ya sehemu za kiolezo zinazohitajika kusasishwa.','%d part reference updated.'=>'%d marejeo ya sehemu yamesasishwa.' . "\0" . '%d marejeo ya sehemu yamesasishwa.','Invalid language.'=>'Lugha si sahihi.','Template part not found or not stored in the database.'=>'Sehemu ya kiolezo hakipatikani au hakijahifadhiwa kwenye hifadhidata.','Template part has no content.'=>'Sehemu ya kiolezo hakina maudhui.','No navigation references needed updating.'=>'Hakuna marejeo ya urambazaji yanayohitajika kusasishwa.','%d navigation reference updated.'=>'%d marejeo ya urambazaji yamesasishwa.' . "\0" . '%d marejeo ya urambazaji yamesasishwa.','No AI provider configured.'=>'Mtoa huduma wa AI hajaanzishwa.','Missing pattern name or language.'=>'Jina la muundo au lugha inakosekana.','Pattern not found.'=>'Muundo haujapatikana.','Pattern has no content to translate.'=>'Muundo haujashikilia maudhui ya kutafsiriwa.','AI provider returned an empty response.'=>'Mtoa huduma wa AI alirudisha majibu tupu.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Muundo umetafsiriwa na kuhifadhiwa. Nakili maudhui kwenye chapisho lako la CPT kupitia mhariri wa kiolezo au tumia kama mwanzo wa Kiolezo kinachoweza kutumika tena.','Invalid template type.'=>'Aina ya kiolezo si sahihi.','Template "%s" already exists.'=>'Kiolezo "%s" tayari kipo.','"%s" created.'=>'"%s" imetengenezwa.','Invalid template part.'=>'Sehemu ya kiolezo si sahihi.','Template part "%s" already exists.'=>'Sehemu ya kiolezo "%s" tayari kipo.','"%1$s" created. %2$d template updated.'=>'"%1$s" imetengenezwa. %2$d kiolezo kimesasishwa.' . "\0" . '"%1$s" imetengenezwa. %2$d kiolezo kimesasishwa.','Page'=>'Ukurasa','Single'=>'Moja','Search'=>'Tafuta','Search Results'=>'Matokeo ya Utafutaji','Archive'=>'Makala','Front Page'=>'Ukurasa wa Mbele','Single: %s'=>'Moja: %s','Single %s'=>'Moja %s','Archive: %s'=>'Hifadhi: %s','%s Archive'=>'Hifadhi %s','No source content found to translate.'=>'Hakuna maudhui ya chanzo yaliyopatikana ya kutafsiri.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Imetafsiriwa. Pitia kwenye Mhariri wa Tovuti — viungo vya ndani, URLs za urambazaji, na majina ya kiolezo hayasaswi kiotomatiki.','Navigation not found.'=>'Uelekeo haujapatikana.','Navigation has no content to translate.'=>'Uelekeo haujakuwa na maudhui ya kutafsiri.','"%1$s %2$s" saved.'=>'"%1$s %2$s" imehifadhiwa.','Translate page…'=>'Tafsiri ukurasa…','Generate content…'=>'Tengeneza maudhui…','AI Behaviour Preset'=>'Mipangilio ya Tabia za AI','Custom'=>'Maendeleo Maalum','Global default (%s)'=>'Chaguo-msingi duniani kote (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Inabadilisha mipangilio ya AI kwa Tafsiri na Uundaji wa Maudhui kwenye ukurasa huu. Maagizo ya maoni maalum ya tovuti yote (Mipangilio → Tabia) yanajumuishwa kila wakati kwenye kila ombi bila kujali chaguo hili.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Inabadilisha mipangilio ya AI kwa Tafsiri na Uundaji wa Maudhui kwenye ukurasa huu. Vipengele vingine vyote vinatumia mipangilio ya jumla kila wakati.','Close'=>'Funga','Translate missing'=>'Tafsiri isiyokamilika','From'=>'Kutoka','Retranslate'=>'Tafsiri tena','Translating…'=>'Inatafsiri…','Retranslating…'=>'Inatafsiri tena…','✓ Done'=>'✓ Imekamilika','Error'=>'Hitilafu','Navigation posts are translated via the Router tab, not this button.'=>'Maandishi ya urambazaji yanatafsiriwa kupitia kichupo cha Router, si kitufe hiki.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Kuunda tafsiri za aina ya chapisho "%s" kunahitaji muunganisho hai. Tafadhali hakikisha muunganisho unaohitajika umewekwa na kufanya kazi.','No %s version found in this translation group.'=>'Hakuna toleo la %s lililopatikana katika kundi hili la tafsiri.','AI Usage'=>'Matumizi ya AI','Today'=>'Leo','Last 7 days'=>'Siku 7 zilizopita','Last 30 days'=>'Siku 30 zilizopita','All time'=>'Wakati wote','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Matumizi ya token yamekusanywa kwa kipengele, mtoa huduma, na mfano. Yamehifadhiwa kwenye kila simu ya AI iliyofanikiwa; ping za Jaribio la Muunganisho zinachukuliwa kwa makusudi ili zisibakize jumla. Jedwali la msingi linakusanya kila siku — chagua dirisha chini ili kuangalia.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Hakuna matumizi ya AI yaliyorekodiwa bado. Mara editor anapofanya tafsiri, kuunda maelezo ya meta, au kutumia kipengele kingine cha AI, jumla zitajitokeza hapa.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Hakuna matumizi ya AI yaliyorekodiwa katika dirisha lililochaguliwa (%s). Chagua wingi zaidi juu.','Feature'=>'Kipengele','Provider'=>'Mtoa huduma','Model'=>'Mfano','Requests'=>'Maombi','Input tokens'=>'Token za ingizo','Output tokens'=>'Token za matokeo','Total tokens'=>'Jumla ya token','Total'=>'Jumla','API Keys'=>'Vifunguo vya API','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Vifunguo vinahifadhiwa kwa usalama kwa AES-256-CBC kabla havijasomwa kwenye hifadhidata ya WordPress. Siri ya usimbuaji inatokana na chumvi za uthibitishaji wa WordPress (wp-config.php), kwa hivyo funguo za maandishi hayagusi hifadhidata kamwe.','API Key'=>'Funguo la API','Paste your API key…'=>'Bandika funguo lako la API…','✓ Configured'=>'Imesasishwa','✗ Not configured'=>'Hijasasishwa','Test connection'=>'Jaribu muunganisho','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Acha tupu ili kuhifadhi funguo iliyopo. Ingiza thamani mpya kuibadilisha.','Remove stored key'=>'Ondoa funguo iliyohifadhiwa','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Funguo hili kwa sasa linatolewa na seva %s na haliwezi kuondolewa hapa. Ingiza funguo mpya juu ili kuilinda na thamani ya hifadhidata.','environment variable'=>'mabadiliko ya mazingira','PHP constant'=>'kifungo cha PHP','Alternative (server-side):'=>'Mbali (upande wa seva):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Pia unaweza kufafanua funguo kama mabadiliko ya mazingira au mabadiliko ya PHP (mfano katika wp-config.php). Vyanzo hivyo vinatumika kiotomatiki kama mbadala wakati hakuna funguo ya hifadhidata iliyohifadhiwa.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Ili kutumia siri ya usimbuaji wa desturi (badala ya thamani ya wp_salt iliyotolewa), ongeza hii katika wp-config.php:','Unknown provider.'=>'Mtoa huduma haijulikani.','No API key configured for this provider.'=>'Hakuna funguo ya API iliyowekwa kwa mtoa huduma huu.','Could not instantiate the provider.'=>'Haiwezi kuanzisha mtoa huduma.','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Mtoa huduma haukutoa maandishi. Angalia kumbukumbu za makosa za WordPress kwa sababu kamili ya kushindwa.','Behavior'=>'Tabia','Block Editor'=>'Mhariri wa Block','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge inazuia vipengele viwili vya Gutenberg kwa chaguo-msingi ili kuweka tabia ya uhariri kuwa thabiti kati ya lugha. Chagua hapa ikiwa unahitaji uwezo kamili wa Gutenberg / FSE.','Block locking'=>'Kufunga kwa block','Allow editors to lock individual blocks'=>'Ruhusu wahariri kufunga blocks binafsi','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Inarudisha tena Gutenberg\'s canLockBlocks. Inafaa kwa templates za uhariri zinazohitaji kuzuia wachangiaji kuhamisha au kufuta blocks fulani.','Template mode'=>'Hali ya template','Allow Gutenberg template-editing mode on post screens'=>'Ruhusu hali ya uhariri wa template wa Gutenberg kwenye skrini za chapisho','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Inarudisha tena supportsTemplateMode. Muhimili kwa mchakato wa Uhariri wa Tovuti Kamili ambapo ubadilishaji wa template wa kiwango cha chapisho ni nia.','Compliance Preset'=>'Preset ya Uzingatiaji','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Hali kali ya uhifadhi kwa maudhui ya kisheria, kanuni, matibabu, au ya kiufundi. Wakati iko, kila kipengele cha AI kinatumia joto la sampuli ya chini na huongeza kifungu cha chini kwa amri ya mfumo — istilahi, nambari za makala, vitengo, majina ya chapa, na lugha za kanuni huhifadhiwa verbatim badala ya kufupishwa.','Global AI preset'=>'Preset ya AI Ulimwenguni','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, kwa kila kipengele','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Huweka tabia chaguo-msingi ya AI kwa vipengele vyote vya tovuti. Chapisho binafsi kinaweza kubadilisha hii kwa Tafsiri na Uundaji wa Maudhui kupitia sanduku la meta la Lingua Forge.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Kawaida hutumia joto la kila kipengele kilichopimwa: Tafsiri T=0.2 (sahihi), Tafsiri Haraka T=0.4, Mwandishi wa Maudhui T=0.6 (ubunifu). Preset nyingine hutumia joto moja lililowekwa kwa vipengele vyote.','Technical / Scientific instructions'=>'Maagizo ya Kiufundi / Sayansi','Legal / Compliance instructions'=>'Maagizo ya Kisheria / Uzingatiaji','Creative / Marketing instructions'=>'Maagizo ya Ubunifu / Masoko','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Acha tupu ili kutumia chaguo-msingi cha kujengwa ndani. Kufuta chaguo lililohifadhiwa kunarudisha chaguo-msingi wakati wa hifadhi inayofuata.','View built-in default'=>'Tazama chaguo-msingi cha kujengwa ndani','Translation Memory'=>'Kumbukumbu ya Tafsiri','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Hifadhi sawa za tafsiri kwenye kiwango cha block ili maudhui yanayoweza kutumika tena (viambatanisho vya chini, upendeleo wa upande, accordions, sehemu za kisheria zenye boilerplate nyingi) zisitoe wito wa API kila wakati. Wakati imewezeshwa, mchakato wa tafsiri huparsing kila chapisho kuwa blocks, huangalia kila block kwenye hifadhi, na hupeleka blocks zisizo na hifadhi pekee kwa AI kwa ombi moja la kundi. Mabadiliko ya kamusi na mabadiliko ya preset ya Uzingatiaji huondoa hifadhi za tafsiri zinazohusika kiotomatiki. Tazama takwimu na safisha hifadhi chini ya Matengenezo.','Enable block-level translation cache reuse across posts'=>'Wezesha upyaji wa hifadhi ya tafsiri kwenye block kwa posts','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Kwa sasa inakosewa kwa posts zinazotumia vigezo vya placeholder vya block-comment (wp:details fields za muhtasari, n.k.) — zinapita kwa njia ya tafsiri ya wito mmoja iliyopo.','General'=>'Jumla','Light'=>'Nuru','Meta Description, Excerpt Generator'=>'Maelezo ya Meta, Mwandishi wa Muhtasari','Quality'=>'Ubora','Translation, Content Generator'=>'Tafsiri, Mwandishi wa Maudhui','Active Provider'=>'Mtoa huduma wa Sasa','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Kwa sasa urithi kutoka kwa kifungo cha %s. Kuchagua thamani hapa kutaleta mabadiliko.','Models'=>'Miundo','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Vipengele vimegawanywa katika ngazi mbili. Ingiza kitambulisho halisi cha mfano kwa kila ngazi na mtoa huduma. Acha uwanja tupu ili kutumia chaguo-msingi cha ndani (kinachoonyeshwa kama nafasi ya kujaza). Mifano ya mtoa huduma anayeendesha pekee ndiyo inaitwa wakati wa runtime — weka zingine mapema ikiwa unakusudia kubadilisha.','active'=>'kinachofanya kazi','overridden'=>'kimezuiwa','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tip: ili kurejesha mfano kwa chaguo-msingi cha ndani, safisha uwanja na hifadhi.','Glossary'=>'Kamusi','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Jedwali la istilahi linaloswa na mtumiaji kwa kila lugha. Viingilio vinaongezwa kwenye maelekezo ya mfumo wa tafsiri ili AI itumie maneno yanayopendelewa kwa utaratibu — muhimu kwa msamiati wa sekta ("kWp", "PPA", "sehemu ya kuunganishwa"), majina ya chapa ambayo hayapaswi kutafsiriwa, na maneno ya kanuni za udhibiti zilizowekwa. Sehemu zote za lugha ni hiari: acha "Lugha ya Chanzo" tupu ili kutumia kiingilio bila kujali unapotafsiri kutoka kwa lugha gani; acha "Lugha ya Malengo" tupu ili kuitekeleza kwa lugha zote za malengo kwa pamoja.','Glossary entry added.'=>'Kuingiza kamusi ya msamiati kumetokea.','Glossary entry removed.'=>'Kufuta kamusi ya msamiati.','Could not add entry: source term and target term are required.'=>'Haiwezi kuongezea kiingilio: neno la chanzo na neno la malengo linahitajika.','Could not save the glossary entry.'=>'Haiwezi kuokoa kiingilio cha kamusi ya msamiati.','Source language'=>'Lugha ya Chanzo','— Any —'=>'— Yoyote —','Target language'=>'Lugha ya Malengo','— Any target —'=>'— Malengo yote —','Filter'=>'Kichujio','Reset'=>'Washa upya','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Hakuna viingilio vya kamusi vinavyolingana na kichujio cha sasa. Futa kichujio ili kuona viingilio vyote, au ongeza kiingilio kipya chini.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Hakuna viingilio vya kamusi bado. Weka chini ili kuanza kutekeleza istilahi katika tafsiri.','Source term'=>'Neno la Chanzo','Target term'=>'Neno la Malengo','Source lang'=>'Lugha ya Chanzo','Target lang'=>'Lugha ya Malengo','Notes'=>'Maelezo','any'=>'yote','Delete this glossary entry?'=>'Unataka kufuta kiingilio hiki cha kamusi? ','Delete'=>'Futa','Add new entry'=>'Ongeza kiingilio kipya','The phrase as it appears in the source text.'=>'Sehemu kama ilivyoonekana katika maandishi ya chanzo.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Jinsi inapaswa kuonekana katika tafsiri. Andika thamani ile ile na neno la chanzo ili kuagiza AI kuilinda kwa maneno halisi.','— Any source language —'=>'— Yoyote ya lugha ya chanzo —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Acha tupu kwa majina ya chapa na maneno yasiyotegemea lugha ambayo yanapaswa kutekelezwa bila kujali lugha tunayotafsiri kutoka.','— Any target language —'=>'— Yoyote ya lugha ya malengo —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Acha tupu ili kiingilio hiki kiweze kutumika kwa lugha zote za malengo — bora kwa majina ya chapa, kifupi, na maneno yanayopaswa kuhifadhiwa kwa maneno halisi katika kila tafsiri.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Muktadha wa hiari kwa wahariri (kama vile "ASIC = Circuit ya Maombi Mahususi; ihifadhi kwa Kiingereza katika muktadha wa kiufundi").','Add entry'=>'Ongeza kiingilio','Limits'=>'Mipaka','Authors and above (edit_published_posts)'=>'Waandishi na zaidi (hariri_maandishi_yaliyochapwa)','Contributors and above — default (edit_posts)'=>'Wachangia na zaidi — chaguo-msingi (hariri_maandishi)','Editors and above (edit_others_posts)'=>'Wahariri na zaidi (hariri_wa_waandishi_wengine)','Administrators only (manage_options)'=>'Wasimamizi pekee (simamia_mipangilio)','AI Limits & Security'=>'Mipaka na Usalama wa AI','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Kataza kiasi cha matumizi ya AI kinachoweza kuzalishwa na tovuti na kuzuia majukumu ya watumiaji wanaoweza kuanzisha simu za AI zilipwa. Inachukua nafasi ya kikomo cha kila mtumiaji (ombi 30 / dakika, kilichowekwa kwa nguvu) kinacholinda dhidi ya mizunguko ya kipekee ya mtumiaji.','Daily request limit'=>'Kikomo cha maombi ya kila siku','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Kikomo cha tovuti kwa maombi ya AI kwa siku ya UTC (kinahesabu tafsiri za Zana na marekebisho ya kizuizi). Kiwango kinarejeshwa saa sita usiku wa UTC. Weka 0 ili kuzima kikomo.','Minimum role'=>'Hali ya chini','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Uwezo wa WordPress wa chini kabisa unaoruhusiwa kuanzisha vipengele vya AI. Kuimarisha hili kwenye tovuti za waandishi wengi kunazuia Wachangia au akaunti za majaribio kuendesha simu za AI zilipwa. Pitia kwa kila kipengele kupitia kichujio cha "linguaforge_required_capability".','Translation Limits'=>'Mipaka ya Tafsiri','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Dhibiti kiasi cha maudhui yanayopitishwa kwa AI na ukubwa wa majibu yanayoweza kutolewa. Acha uwanja tupu ili kutumia chaguo-msingi cha ndani (kinachoonyeshwa kama mahali pa kuweka). Ongeza thamani hizi ikiwa kurasa kubwa zinakatwa; punguza ili kupunguza gharama za API.','Model tier'=>'Kiwango cha mfano','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Ubora (chaguo-msingi — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Mwanga (haraka na nafuu — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Kiwango cha mfano kinachotumika kwa tafsiri ya kurasa kamili. Ubora unatumia mfano uliowekwa kwenye jedwali la Miundo hapo juu na ni wa kupendekezwa kwa tafsiri sahihi, ya muda mrefu. Badilisha kwa Mwanga ikiwa ni haraka au gharama ndogo ndogo ndizo kipaumbele na maudhui ni mafupi.','Max output tokens'=>'Idadi ya tokeni za matokeo makubwa','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Idadi kubwa ya tokeni ambazo AI inaweza kuzalisha kwa jibu moja la tafsiri. Ikiwa tafsiri inakatwa kimya kimya mwisho, ongeza thamani hii. Chaguo-msingi: 16,000.','Max input characters'=>'Herufi za ingizo za juu zaidi','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Kiwango kikubwa cha wahusika wa maudhui ya chapisho yaliyotumwa kwa AI. 0 inamaanisha hakuna kikomo — maudhui kamili yanatumiwa daima (inapendekezwa). Weka thamani isiyo sifuri ikiwa mtoa huduma wako ana dirisha la muktadha mkali. Onyo linaandikwa kwenye kumbukumbu ya makosa ya PHP kila wakati maudhui yanapunguzwa.','Quick Translation'=>'Tafsiri Haraka','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Tafsiri Haraka hutumiwa kwa hali ya vipande/vipande — vifungu vifupi vinavyotafsiriwa kwa ombi kutoka kwa upau wa zana, mhariri, au popo za kizuizi. Inatumia usanidi tofauti, nyepesi kutoka kwa tafsiri ya ukurasa kamili ili kuweka majibu kuwa ya haraka na yenye gharama nafuu.','Light (default — fast and cost-effective)'=>'Nuru (chaguo-msingi — haraka na yenye gharama nafuu)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Ubora (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Kiwango cha Nuru kinatumia mfano wa haraka uliowekwa kwenye jedwali la Miundo hapo juu (chaguo-msingi: Haiku / Flash). Badilisha kwa Ubora ikiwa unahitaji usahihi wa tafsiri sawa na hali ya ukurasa kamili kwa vipande.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Wahusika wa juu zaidi wanaowezekana na AI inaweza kuzalisha kwa kila tafsiri ya haraka. Chagua: 2,000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Wahusika wa juu zaidi wanaokubaliwa kutoka kwa uwanja wa ingizo. Chaguo-msingi: 8,000.','Content Generator'=>'Kizazi cha Maudhui','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Hudhibiti bajeti ya tokeni na mipaka ya ingizo kwa kipengele cha Kizazi cha Maudhui cha AI. Acha mashamba tupu ili kutumia chaguo-msingi zilizojengwa ndani.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Wahusika wa juu zaidi wanaowezekana na AI wanaweza kuzalisha kwa kila uendeshaji wa kizazi. Ongeza ikiwa makala kamili yanakatwa. Chaguo-msingi: 8,192.','Max hints characters'=>'Wahusika wa vidokezo vya juu zaidi','Maximum characters read from the Hints field. Default: 2 000.'=>'Wahusika wa juu zaidi wanaosomwa kutoka kwa uwanja wa Vidokezo. Chaguo-msingi: 2,000.','Max context characters'=>'Wahusika wa muktadha wa juu zaidi','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Wahusika wa juu zaidi wa maudhui ya chapisho yaliyopo yanayotumwa kwa AI kama muktadha wa mbegu wakati hakuna Vidokezo vinavyotolewa. Chaguo-msingi: 6,000.','Maintenance'=>'Matengenezo','Language Overrides'=>'Mabadiliko ya Lugha','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Pakua faili zilizokusanywa za .mo kubadilisha maneno ya programu za watu wengine kwa maeneo maalum — kwa mfano, tafsiri maalum ya VikBooking inayotumia "apartment" badala ya "room". Faili lazima zifuate muundo wa jina la WordPress: {textdomain}-{locale}.mo (mfano, vikbooking-ca.mo). Zina hifadhiwa kwenye folda ya uploads na huishi baada ya sasisho la programu.','Override file uploaded successfully.'=>'Faili ya mabadiliko imepakuliwa kwa mafanikio.','Override file deleted.'=>'Faili ya mabadiliko imefutwa.','No file was selected.'=>'Hakuna faili iliyochaguliwa.','Only .mo files are accepted.'=>'Faili za .mo pekee zinakubaliwa.','The upload failed — please try again.'=>'Upakuaji umeshindwa — tafadhali jaribu tena.','Could not save the file. Check that the uploads folder is writable.'=>'Haiwezekani kuhifadhi faili. Hakikisha folda ya uploads ina haki ya kuandika.','Invalid filename.'=>'Jina la faili si sahihi.','Security check failed — file path is not permitted.'=>'Uhakiki wa usalama umeshindwa — njia ya faili haikubaliki.','An unknown error occurred.'=>'Hitilafu isiyojulikana imetokea.','Text domain / locale'=>'Uwanja wa lugha / muktadha','Files'=>'Faili','Size'=>'Ukubwa','Delete all files for this override (both .mo and .po)?'=>'Futa faili zote za mabadiliko haya (zote .mo na .po)?','No override files uploaded yet.'=>'Hakuna faili za mabadiliko zilizopakiwa bado.','Upload .mo file'=>'Pakua faili ya .mo','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Inakubali faili zilizokusanywa za .mo pekee. Jina la faili lazima zifuate muundo wa {textdomain}-{locale}.mo. Kupakia faili lenye jina sawa na la zamani kutalibadilisha.','Upload Override'=>'Pakua Mabadiliko','Loco Translate — Copy to Safe Storage'=>'Loco Tafsiri — Nakili kwa Hifadhi Salama','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate hifadhi tafsiri zake maalum katika wp-content/languages/loco/ — mahali ambapo inaweza kufutwa kwa kimya na sasisho la WP, kufanywa upya kwa programu, au ikiwa Loco Translate yenyewe inatoweka. Nakili faili hapa huziweka kwenye saraka ya Lingua Forge i18n-overrides, ambayo huendelea kuwa hai kupitia matukio yote hayo na hujumuishwa kiotomatiki kila wakati.','File copied to safe storage successfully.'=>'Faili imehamishwa kwa mafanikio kwenye hifadhi salama.','Source file not found.'=>'Faili ya chanzo haipatikani.','Could not copy the file. Check that the uploads folder is writable.'=>'Haiwezekani kunakili faili. Hakikisha folda ya uploads ina haki ya kuandika.','Invalid file reference.'=>'Rejea ya faili si sahihi.','Type'=>'Aina','✓ In safe storage'=>'✓ Katika hifadhi salama','Copy to safe storage'=>'Nakili kwenye hifadhi salama','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Hakuna faili maalum za Loco Translate bado. Zinaonekana hapa mara tu unapohifadhi tafsiri kwenye Loco Translate.','AI Cache'=>'Cache ya AI','Lingua Forge caches AI-generated translations, meta descriptions, excerpts, and generated content per-post so unchanged inputs do not re-trigger a paid API call. Cached entries are automatically invalidated when their inputs change. Clear the cache manually to reclaim database space, force a resync after switching providers or editing prompt templates, or troubleshoot a cache-related issue.'=>'Lingua Forge huhifadhi tafsiri zinazozalishwa na AI, maelezo ya meta, vipande, na maudhui yaliyotengenezwa kwa kila chapisho ili maneno yasiyobadilika yasirejeshe wito wa API uliolipwa. Vipengee vilivyohifadhiwa kiotomatiki vinavunjwa wakati waingizo yao hubadilika. Futa cache kwa mikono ili kurejesha nafasi ya hifadhidata, kulazimisha upya baada ya kubadilisha watoa huduma au kuhariri templates za maombi, au kutatua tatizo la cache.','AI cache cleared. %d entry was removed.'=>'Cache ya AI imefutwa. Kipengee %d kiliondolewa.' . "\0" . 'Cache ya AI imefutwa. Vipengee %d vimeondolewa.','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Futa matokeo yote ya AI yaliyohifadhiwa? Maombi yajayo yataanzisha wito mpya wa API hadi cache itakapojengwa upya.','Clear AI Cache'=>'Futa Kumbukumbu za AI','Debug Files'=>'Faili za Kagua','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Wakati kumbukumbu za kagua zinapokua zimewezeshwa (kupitia kitufe cha chini au kwa kufafanua LINGUAFORGE_AI_DEBUG katika wp-config.php), vipengele vya Tafsiri na template ya FSE huandika maombi yao ya AI na majibu kwenye diski kwa ajili ya utatuzi wa matatizo. Tumia sehemu hii kufuatilia matokeo hayo na kuyaondoa mara umepata unachohitaji — faili zinaweza kukua kwa haraka kwenye kurasa kubwa. Sanidi saraka ya malengo kupitia kichungi cha linguaforge_debug_dir.','Debug files cleared. %d file was removed.'=>'Faili za kagua zimesafishwa. Faili %d imeondolewa.' . "\0" . 'Faili za kagua zimesafishwa. Faili %d zimeondolewa.','Debug logging enabled.'=>'Kumbukumbu za kagua zimewezeshwa.','Debug logging disabled.'=>'Kumbukumbu za kagua zimezimwa.','Debug logging'=>'Kumbukumbu za kagua','Write AI prompts and responses to disk for troubleshooting'=>'Andika maombi ya AI na majibu kwenye diski kwa ajili ya utatuzi wa matatizo','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Imezuiwa kwa nguvu na mabadiliko ya LINGUAFORGE_AI_DEBUG katika wp-config.php. Ondoa mstari huo ili kudhibiti kitufe hiki kutoka hapa.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Imezimwa kwa nguvu na mabadiliko ya LINGUAFORGE_AI_DEBUG katika wp-config.php. Ondoa mstari huo ili kudhibiti kitufe hiki kutoka hapa.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Faili huwasili kwenye saraka iliyo chini. Inafaa kwa utatuzi wa matatizo ya tafsiri — zima mara unapata unachohitaji ili faili zisikusanyike. Pia unaweza kuizuia kutoka wp-config.php kwa kutumia `define( \'LINGUAFORGE_AI_DEBUG\', true );` ambayo inazidi kitufe hiki.','Currently:'=>'Sasa hivi:','✓ Enabled'=>'✓ Imewashwa','✗ Disabled'=>'✗ Imesimamishwa','Directory'=>'Saraka','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Chuja kwa kutumia linguaforge_debug_dir ili kuelekeza matokeo ya kagua mahali pasipo umma.','.txt file(s) in the directory'=>'.txt faili(za) kwenye saraka','Save Debug Setting'=>'Hifadhi Mipangilio ya Kagua','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Futa faili zote za .txt kwenye saraka ya kagua? Saraka yenyewe itabaki ili kuendelea kuandika mafaili ya kagua ya baadaye.','Clear Debug Files'=>'Futa Faili za Kagua','Per-block translation cache shared across posts. Configure on/off in Settings → Behavior. Stats below show what is currently cached; clearing forces every block to be re-translated on next request (useful after upgrading models or to recover database space).'=>'Kuhifadhi cache ya tafsiri kwa kila kipande kinachoshirikiwa kati ya machapisho. Sanidi on/off katika Vipimo → Tabia. Takwimu chini zinaonyesha kile kinachohifadhiwa kwa sasa; kufuta kunalazimisha kila kipande kutafsiriwa tena kwenye ombi lijalo (inafaa baada ya kusasisha mifano au kurejesha nafasi ya hifadhi ya data).','Translation Memory cleared. %d cached block was removed.'=>'Kumbukumbu ya Tafsiri imefutwa. Kipande cha cache %d kiliondolewa.' . "\0" . 'Kumbukumbu ya Tafsiri imefutwa. Vipande %d vya cache vimeondolewa.','Status'=>'Hali','— toggle in Settings → Behavior.'=>'— chaguo katika Vipimo → Tabia.','Cached blocks'=>'Vipande vilivyohifadhiwa','Cumulative cache hits'=>'Mafanikio ya cache ya jumla','(avg %.1f hits/block)'=>'(avg %.1f mafanikio/kipande)','Oldest entry'=>'Kipindi cha zamani zaidi','Newest entry'=>'Kipindi kipya zaidi','Approximate size'=>'Ukubwa wa takriban','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Futa Kumbukumbu ya Tafsiri yote? Tafsiri za baadaye zitajenga tena cache wanapozalishwa.','Clear Translation Memory'=>'Futa Kumbukumbu ya Tafsiri','Uninstall Behaviour'=>'Futa Tabia ya Kifuta','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Hakikisha kinachotokea wakati msimamizi anafuta programu kutoka kwa Plugins → Plugins zilizowekwa → Futa. Mipangilio ya programu na cache za AI daima zinasafishwa. Uteuzi wa lugha na uhusiano wa tafsiri huzingatiwa kwa chaguo-msingi ili kusudi la kufuta au kufunga upya liweze kuendelea mahali pa kuacha.','Uninstall setting saved.'=>'Mipangilio ya kufuta imesimamiwa.','Delete content data on uninstall'=>'Futa data ya maudhui wakati wa kufuta','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Pia futa uteuzi wa lugha, uhusiano wa tafsiri, maelezo ya meta, kamusi, na Kumbukumbu ya Tafsiri wakati programu inafutwa.','Warning:'=>'Onyo:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Ikiwa imeshakaguliwa, kufuta programu kutafuta kwa muda mrefu utafuta uteuzi wa lugha, uhusiano wa tafsiri, maelezo ya meta, mipangilio ya ukurasa, kamusi ya AI, na Kumbukumbu ya Tafsiri kwa kila chapisho kwenye tovuti hii. Hii haiwezi kurejeshwa. Acha ishiwi isipokuwa unatoa msaada wa lugha nyingi kutoka kwa tovuti.','Save Uninstall Setting'=>'Hifadhi Mipangilio ya Kufuta','Router'=>'Router','Primary language saved.'=>'Lugha kuu imehifadhiwa.','Permalink rules flushed successfully.'=>'Sheri za permalink zimefutwa kwa mafanikio.','Primary Language'=>'Lugha Kuu','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Lugha kuu daima hutumika kwenye mzizi wa tovuti yako — hakuna kiambishi cha URL katika hali ya njia, hakuna subdomain ya lugha katika hali ya subdomain. Lugha nyingine zote hutumia au kiambishi cha /lang/ (mfano example.com/de/) au subdomain ya lugha (mfano de.example.com), kulingana na mpangilio wa muundo wa URL hapo chini.','Primary language'=>'Lugha kuu','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Baada ya kubadilisha lugha kuu, safisha permalink (sehemu chini) ili kusasisha njia ya URL.','URL structure'=>'Muundo wa URL','Path prefix — example.com/de/'=>'Kipindi cha njia — example.com/de/','Subdomain — de.example.com/'=>'Subdomain — de.example.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Mode ya subdomain inahitaji seva yako ya wavuti kuelekeza subdomains zote za lugha (kama de.example.com) kwa usakinishaji huu wa WordPress. Baada ya kubadilisha mode, fanya usafi wa sheria za permalink na safisha cache yoyote. Ikiwa URL yako ya nyumbani inajumuisha www (kama www.example.com), tumia kichujio cha lf_base_domain kuweka domain kuu bila www ili subdomains zifanywe kwa usahihi.','Browser language redirect'=>'Uelekeaji wa lugha wa kivinjari','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Uelekeza wageni kwa lugha yao wanayoipendelea kulingana na kichwa cha Accept-Language cha kivinjari','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Wakati kinachozimwa, wageni wa mara ya kwanza wasio na keki ya lugha na bila kiambishi cha lugha kwenye URL wanapelekwa kwa toleo la lugha linalolingana zaidi. Uelekezaji huachwa ikiwa lugha inayopendelewa na kivinjari si miongoni mwa lugha zinazofanya kazi za router. Mara mgeni anapochagua lugha kupitia kisakinishi, keki inachukua kipaumbele na kichwa cha kivinjari hakitazingatiwa kwa ziara zijazo.','Save Router Settings'=>'Hifadhi Mipangilio ya Router','Flush Permalinks'=>'Fanya usafi wa Permalinks','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Inarejesha sheria za uandishi wa WordPress ili viambishi vya URL, slug za lugha, na uandishi wa makala viwe vinaendana. Inahitajika baada ya kubadilisha lugha kuu au kuongeza msaada wa lugha mpya.','Flush Permalink Rules'=>'Fanya usafi wa Sheria za Permalink','Active Languages'=>'Lugha Zinazotumika','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Lugha zinazojulikana kwa sasa kwa router (zinatokana na pakiti za lugha za WordPress zilizowekwa pamoja na lugha kuu). Weka pakiti za lugha za ziada katika sehemu iliyo chini ili kufanya lugha zaidi zipatikane kwa uelekezaji na tafsiri.','%d locale pack installed.'=>'%d pakiti za lugha zimewekwa.' . "\0" . '%d pakiti za lugha zimewekwa.','Install a Language'=>'Sakinisha Lugha','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Pakua na usakinishe pakiti ya lugha kuu ya WordPress moja kwa moja kutoka WordPress.org. Mara baada ya kusakinisha, lugha inapatikana kwa uelekezaji wa URL na mchakato wa tafsiri wa AI. Orodha ya lugha zinazopatikana inachukuliwa kwa ombi — bofya kitufe chini ili kuipakua.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Sakinisho la lugha limezimwa kwenye seva hii. Kigezo cha DISALLOW_FILE_MODS kimewekwa katika wp-config.php. Sakinisha pakiti za lugha kwa mikono kupitia WP-CLI: wp language core install de_DE','Load available languages'=>'Pakua lugha zinazopatikana','— select a language —'=>'— chagua lugha —','Install'=>'Sakinisha','Language Setup'=>'Mipangilio ya Lugha','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Hakuna lugha za ziada zilizowekwa. Sakinisha pakiti ya lugha hapo juu ili kuwezesha muundo wa kiolezo.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Chagua lugha ili kuendesha muundo wa FSE, sehemu za muundo, na menyu za urambazaji.','Forbidden'=>'Kizuizi','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Sakinisho la lugha limezimwa kwenye seva hii (DISALLOW_FILE_MODS imewekwa).','Invalid locale code.'=>'Msimbo wa lugha si sahihi.','Language %s installed successfully.'=>'Lugha %s imewekwa kwa mafanikio.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Sakinisho la pakiti ya lugha limegonga. Lugha inaweza tayari imewekwa, msimbo wa lugha si sahihi, au seva yako inazuia uandishi wa faili.','Navigations'=>'Viongozi','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Utaratibu wa urambazaji unahitaji mtoa huduma wa AI anayeishi. Sanidi ufunguo wa API kwenye kichupo cha Funguo za API.','Navigation'=>'Urambazaji','Action'=>'Kitendo','Re-translate'=>'Tafsiri tena','CPT Block Patterns'=>'Mipango ya Block CPT','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Mipango ya block zilizoorodheshwa kwa aina za machapisho maalum. Tumia kitufe cha Tafsiri kuunda toleo la lugha. Yaliyomo yaliyotafsiriwa yanahifadhiwa hapa na yanaweza kuhamishwa kwenye chapisho lolote la CPT kutoka kwa mhariri wa block au kutumika kama hatua ya kuanzia kwa Pattern iliyosawazishwa (Reusable Block).','Pattern'=>'Mfano','Post Types'=>'Aina za Machapisho','✓ Translation saved'=>'✓ Tafsiri imehifadhiwa','View'=>'Tazama','Template Parts'=>'Sehemu za Muundo','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Nakili za lugha maalum za mandhari. Mara baada ya kuundwa, templates huboreshwa kurejelea sehemu maalum za lugha.','Part'=>'Sehemu','Status / Actions'=>'Hali / Vitendo','Fix Links'=>'Rekebisha Viungo','Fix Nav'=>'Rekebisha Urambazaji','Create'=>'Unda','Templates'=>'Mifano','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Mifano ya FSE iliyopandikizwa kutoka kwa mandhari hai. Unda kisha ibadilike kwenye Mhariri wa Tovuti.','Actions'=>'Vitendo','Fix Parts'=>'Rekebisha Sehemu','Create missing'=>'Unda zilizokosewa','Translate all'=>'Tafsiri zote','Fix all parts'=>'Rekebisha sehemu zote','Fix all links'=>'Rekebisha viungo vyote','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','Testing…'=>'Inajaribu…','✓ Connection OK'=>'✓ Muunganisho mzuri','✗ Failed:'=>'✗ Imeshindwa:','No response from provider — check the error log for details.'=>'Hakuna majibu kutoka kwa mtoa huduma — angalia kumbukumbu za makosa kwa maelezo.','Network error — could not reach the WordPress AJAX endpoint.'=>'Hitilafu ya mtandao — haikuweza kufikia mwisho wa AJAX wa WordPress.','Loading…'=>'Inapakia…','Installing…'=>'Inasakinishwa…','✓ Language installed.'=>'✓ Lugha imewekwa.','✗ Error:'=>'✗ Hitilafu:','Creating…'=>'Inaundwa…','✓ All templates created.'=>'✓ Kila kiolezo kimeundwa.','Some templates could not be created.'=>'Baadhi ya kiolezo hakikuweza kuundwa.','✓ All parts created.'=>'✓ Sehemu zote zimetengenezwa.','Some parts could not be created.'=>'Sehemu zingine hazikuweza kuundwa.','✓ All translated.'=>'✓ Zote zimefasirishwa.','Some translations failed.'=>'Baadhi ya tafsiri zimeshindwa.','Review carefully — links and slugs not updated.'=>'Kagua kwa makini — viungo na slugs havijasasishwa.','Fixing…'=>'Inarekebishwa…','✓ Links fixed.'=>'✓ Viungo vimerekebishwa.','Some link fixes failed.'=>'Baadhi ya marekebisho ya viungo yameshindwa.','✓ Parts fixed.'=>'✓ Sehemu zimerekebishwa.','Some part fixes failed.'=>'Sehemu zingine hazikuweza kurekebishwa.','✓ Nav refs fixed.'=>'✓ Marejeo ya urambazaji yamerekebishwa.','Some nav ref fixes failed.'=>'Marekebisho ya marejeo ya urambazaji yameshindwa.','✓ Pattern translated.'=>'✓ Mfano umefasirishwa.','Pattern translation failed.'=>'Ufasirishwa kwa mfano umeshindwa.','Hide'=>'Ficha','Built-in preset instructions:'=>'Maagizo ya awali yaliyowekwa ndani:','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Hakuna maagizo yaliyowekwa ndani — kila kipengele cha AI kinatumia chaguo zake zilizobinafsishwa. Jaza uwanja wa Maagizo ya Maelekezo ya Maoni ya Kibinafsi hapa chini ili kuongeza kanuni zako za tovuti kwa ujumla.','Settings'=>'Mipangilio','You do not have permission to manage these settings.'=>'Huna ruhusa ya kusimamia mipangilio hii.','Lingua Forge — Settings'=>'Lingua Forge — Mipangilio','Settings saved.'=>'Mipangilio imehifadhiwa.','Save Settings'=>'Hifadhi Mipangilio','Standard'=>'Kawaida','Technical / Scientific'=>'Kitaaluma / Sayansi','Legal / Compliance'=>'Kisheria / Uzingatiaji','Creative / Marketing'=>'Ubunifu / Masoko','Full Article'=>'Makala Kamili','Introduction only'=>'Utangulizi tu','Structured Outline'=>'Muhtasari wa Muundo','Generate Content'=>'Tengeneza Yaliyomo','Hints'=>'Vidokezo','Key points, ideas, or structure to build from…'=>'Vitu muhimu, mawazo, au muundo wa kujenga kutoka...','Tone'=>'Mwelekeo','Output'=>'Matokeo','Generate Excerpt'=>'Unda Kipengele','Generate Meta Description'=>'Unda Maelezo Meta','Translate Content'=>'Tafsiri Maudhui','Mode'=>'Hali','Full post'=>'Ujumbe kamili','Translate chunk'=>'Tafsiri sehemu','Target Language'=>'Lugha inayolengwa','Text to translate'=>'Maandishi ya kutafsiri','Paste a footnote, sentence, or any snippet here…'=>'Bandika nukuu ya mguu wa ukurasa, sentensi, au kipande chochote hapa...','Also generate meta description'=>'Pia tengeneza maelezo meta','Translated Names'=>'Majina yaliyotafsiriwa','Name displayed in this language. Leave empty to use the source name.'=>'Jina linaloonyeshwa kwa lugha hii. Acha tupu ili kutumia jina la chanzo.','Too many AI requests. Please retry in %d seconds.'=>'Orodha nyingi za AI. Tafadhali jaribu tena kwa sekunde %d.','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Kiwango cha AI cha kila siku kimefikia (%1$d maombi). Kinarejeshwa saa %2$s UTC.','View Lingua Forge details'=>'Tazama maelezo ya Lingua Forge','View details'=>'Tazama maelezo','Visit plugin site'=>'Tembelea tovuti ya programu-jalizi','%d language not yet linked'=>'Lugha %d bado haijaundwa' . "\0" . 'Lugha %d bado hazijaundwa','This is the source page. Footnotes are edited directly in the block editor.'=>'Hii ni ukurasa wa chanzo. Nukuu za mguu wa ukurasa huhaririwa moja kwa moja kwenye mhariri wa vikundi.','No source page linked yet.'=>'Bado hakuna ukurasa wa chanzo umeunganishwa.','The source page has no footnotes.'=>'Ukurasa wa chanzo haujakuwa na nukuu za mguu wa ukurasa.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Nukuu hizi za mguu wa ukurasa zinatoka kwenye ukurasa wa chanzo na zinaonyeshwa hapa kwa marejeo tu. Ziongeze kwenye ukurasa huu kwa kutumia mhariri wa vikundi.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d kiolezo zilizotafsiriwa kutoka kwa mandhari &#8220;%2$s&#8221; zimehifadhiwa kwenye hifadhidata lakini kwa sasa hazifanyi kazi. Zitatumika tena ikiwa utarejesha hali ya mandhari hiyo. Ili kuhamisha tafsiri zako kwa mandhari mpya, zitengeneze tena kupitia <strong>Mipangilio → Lingua Forge → Router → FSE scaffold</strong>.','Scanning posts for broken language links…'=>'Inasoma machapisho kwa ajili ya viungo vya lugha vilivyovunjika...','Re-scanning…'=>'Inasoma tena...','Scan failed: '=>'Uchunguzi umeshindwa: ','unknown error'=>'hitilafu isiyojulikana','Scan request failed. Please try again.'=>'Ombi la uchunguzi limekosa mafanikio. Tafadhali jaribu tena.','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Hakuna machapisho <strong>{lang}</strong> yaliyopatikana. Hakikisha machapisho yote yaliyotafsiriwa yana Meta ya Lugha iliyowekwa kuwa <strong>{lang}</strong> kwenye sanduku la Meta la Lugha.','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Hakuna viungo vilivyovunjika au makosa ya kiolezo yaliyopatikana kwa <strong>{lang}</strong>. Umechunguza machapisho <strong>{scanned}</strong> na kurasa — ukaguzi wote umepita. Viungo vya sehemu za kiolezo (kichwa, mfinyanzi, upendeleo wa upande) havijajumuishwa hapa — tumia kitufe cha Kutatuwa Sehemu za Kiolezo kuangalia tofauti.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> kiungo kinachoweza kurekebishwa kiotomatiki','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> kiungo kinachohitaji mapitio ya mikono','and'=>'na','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Imepatikana {parts} kati ya <strong>{total}</strong> ya machapisho <strong>{scanned}</strong> yaliyopitiwa kwa <strong>{lang}</strong>.','Post'=>'Uchapishaji','Links'=>'Viungo','link(s)'=>'kiungo(viungo)','Fix'=>'Rekebisha','✅ Fixed ({n})'=>'✅ Imerekebishwa ({n})','⚠ No changes — re-scan?'=>'⚠ Hakuna mabadiliko — tena uchunguzi?','⚠ No changes'=>'⚠ Hakuna mabadiliko','❌ Failed'=>'❌ Imeshindwa','Done — {done} of {total} post(s) fixed.'=>'Imekamilika — machapisho {done} kati ya {total} yamerekebishwa.','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} hayakuwa na viungo vinavyoweza kubadilishwa — chunguza tena kwa uchunguzi)','Fixing {n} / {total}…'=>'Rekebisha {n} / {total}…','URL could not be mapped to a post — check the link target exists'=>'URL haikuweza kuambatana na chapisho — angalia kama lengo la kiungo lipo','No {lang} translation registered (TRID missing)'=>'Hakuna tafsiri ya {lang} iliyosajiliwa (TRID inakosekana)','Translation found but permalink could not be generated'=>'Utaratibu umegunduliwa lakini kiungo cha kudumu hakikuweza kutengenezwa','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> njia/nyingine zilizobaki','📍 Stale path (page moved)'=>'📍 Njia/nyingine zilizobaki (ukurasa uhamishiwa)','{n} stale path(s)'=>'{n} njia/nyingine zilizobaki','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> tatizo la kiolezo','📄 Wrong template'=>'📄 Kiolezo kisicho sahihi','Expected: {expected}'=>'Inatarajiwa: {expected}','Current: {current}'=>'Sasa: {current}','Template "{expected}" does not exist — create it in the Site Editor first.'=>'Kiolezo "{expected}" hakipo — tengeneza kwanza kwenye Mhariri wa Tovuti.','Fix Template'=>'Rekebisha Kiolezo','✅ Template fixed'=>'✅ Kiolezo kimerekebishwa','Internal Link Fixer'=>'Rekebisha Kiungo cha Ndani','Fix All'=>'Rekebisha Yote','Re-scan'=>'Re-scan','Language Switcher'=>'Kigeuzi cha Lugha','Displays the Lingua Forge language switcher.'=>'Inaonyesha kigeuzi cha lugha cha Lingua Forge.','Language'=>'Lugha','Display'=>'Onyesha','Language label'=>'Lebo ya lugha','Icon only'=>' Picha pekee','Icon + label'=>'Picha + lebo','Dropdown direction'=>'Mwelekeo wa orodha','Down'=>'Chini','Up'=>'Juu','You do not have permission to read this post.'=>'Huna ruhusa ya kusoma chapisho hili.','Post not found.'=>'Chapisho hakipatikani.','Limit results to pages in the given Lingua Forge language code.'=>'Lenga matokeo kwa kurasa zilizo katika msimbo wa lugha wa Lingua Forge uliotolewa.','Meta Description'=>'Maelezo ya Meta','Using custom meta description.'=>'Kutumia maelezo maalum ya meta.','Prefilled from excerpt. Edit to override.'=>'Imejazwa kutoka kwa muhtasari. Badilisha ili kuizidi.','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Lenga kwa herufi 120–160. Acha tupu ili kutumia muhtasari wa nyuma.','↺ Refreshing…'=>'↺ Inasasishwa…','Review translation before applying'=>'Kagua tafsiri kabla ya kutumia','Current title'=>'Kichwa cha sasa','Translated title'=>'Kichwa kilichotafsiriwa','Current content (will be overwritten)'=>'Yaliyomo ya sasa (yatafutwa)','Translated content'=>'Yaliyomo yaliyotafsiriwa','Footnotes payload (advanced)'=>'Msaada wa maelezo ya mguu wa ukurasa (ya juu)','Generated meta description'=>'Maelezo ya meta yaliyotengenezwa','Saved to the meta description field when you apply.'=>'Imehifadhiwa kwenye uwanja wa maelezo ya meta unapoomba.','Cancel'=>'Ghairi','Apply translation'=>'Tumia tafsiri','Generated Content'=>'Yaliyomo yaliyotengenezwa','Refine further:'=>'Boresha zaidi:','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Ongeza maelekezo ili kuboresha rasimu — mfano fupisha, ongeza sehemu ya hitimisho, tumia muundo rasmi zaidi, jumuisha sehemu ya maswali yanayoulizwa mara kwa mara…','↺ Refine'=>'↺ Boresha','Copy markup'=>'Nakili muundo wa maandishi','Apply to Editor'=>'Tumia kwa Mhariri','Copied ✓'=>'Imenakiliwa ✓','Applying…'=>'Inatumika…','Applied ✓'=>'Imethibitishwa ✓','Refining…'=>'Inasafishwa…','Refinement failed — please try again.'=>'Uainishaji umeshindwa — tafadhali jaribu tena.','Refinement'=>'Uainishaji','✓ Refined — review the updated draft above.'=>'✓ Umeboreshwa — hakiki rasimu iliyosasishwa hapo juu.','Request failed — please try again.'=>'Ombi limekosewa — tafadhali jaribu tena.','The editor did not accept the content — please try again.'=>'Mhariri hakukubali maudhui — tafadhali jaribu tena.','Save the post to persist changes.'=>'Hifadhi chapisho ili kudumisha mabadiliko.','Apply failed — please try again.'=>'Umeomba kushindwa — tafadhali jaribu tena.','Copy'=>'Nakili','Apply to Meta Description'=>'Tumia kwa Maelezo ya Meta','Generating…'=>'Inazalishwa…','Generation failed.'=>'Uzalishaji umeshindwa.','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Yaliyomo yamezalishwa — angalia juu ili kuangalia, kuboresha, na kutumia.','Request failed.'=>'Ombi limekosewa.','cached'=>'imehifadhiwa','Translated to:'=>'Imetafsiriwa kwa:','tone'=>'sauti','Content generated'=>'Yaliyomo yamezalishwa','Content ready'=>'Yaliyomo yamekamilika','footnote(s) translated — applied together with content.'=>'Vijisehemu vilivyotafsiriwa — vimewekwa pamoja na yaliyomo.','Chunk translated to:'=>'Sehemu iliyotafsiriwa kwa:','Chunk translated'=>'Sehemu iliyotafsiriwa','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Nakili matokeo na uyatamise mahali panahitajika (kama moja kwa moja kwenye uwanja wa maelezo mafupi).','chars'=>'wahusika','✓ Good length'=>'Urefu mzuri ✓','⚠ Borderline'=>'Hatari ya ukingo ⚠','✗ Too short'=>'Mfupi sana ✗','✗ Too long'=>'Mrefu sana ✗','Target: 140–160 chars for optimal SERP display'=>'Lengo: wahusika 140–160 kwa kuonyesha bora kwenye SERP','SEO character-count info'=>'Habari za idadi ya wahusika za SEO','↺ Refresh'=>'↺ Mvua','Re-generates and updates the cached result.'=>'Inazalisha tena na kusasisha matokeo yaliyohifadhiwa.','← Back'=>'← Rudi nyuma','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Ongeza maelekezo ya kuboresha rasimu — mfano, ifupishe, ongeza sehemu ya hitimisho, tumia muundo rasmi zaidi…','Improve writing'=>'Boresha uandishi','Make formal'=>'Fanya rasmi','Make casual'=>'Fanya kwa kawaida','Make concise'=>'Fupisha','Expand'=>'Panua','Bulletize (•-prefixed)'=>'Fanya kwa alama za orodha (•-kianzio)','Lead paragraph (≤60 w)'=>'Kipande cha kuongoza (≤60 w)','Mark citations needed'=>'Alama za kuashiria mahitaji ya nukuu','Plain language'=>'Lugha rahisi','Translate / Revise'=>'Tafsiri / Badilisha','Translate / Revise block'=>'Kifungu cha Tafsiri / Badilisha','Revision'=>'Uboreshaji','Footnotes'=>'Vijisehemu','Block Content'=>'Yaliyomo ya Kifungu','Revision Type'=>'Aina ya Uboreshaji','Revise'=>'Rekebisha','Footnote Content'=>'Maudhui ya Nukuu','Apply to Block'=>'Tumia kwa Kizuizi','Instructions (optional)'=>'Maagizo (hiari)','Extra guidance — tone, style, constraints, target audience…'=>'Msaada wa ziada — sauti, mtindo, vizuizi, hadhira lengwa…','Extra guidance — tone, style, constraints…'=>'Msaada wa ziada — sauti, mtindo, vizuizi…','↑ Detected from current post'=>'↑ Imegunduliwa kutoka kwa chapisho la sasa','Processing…'=>'Inashughulikiwa…','Failed. Please try again.'=>'Imeshindwa. Tafadhali jaribu tena.','Request failed. Check your connection.'=>'Ombi limeshindwa. Angalia muunganisho wako.','Apply to Footnote'=>'Tumia kwa Nukuu','Quick Translate'=>'Tafsiri Haraka','Paste text, or select text in the editor first…'=>'Bandika maandishi, au chagua maandishi kwenye mhariri kwanza…','Clear input'=>'Futa ingizo','Clear'=>'Futa','Instructions / key points'=>'Maagizo / vidokezo muhimu','Describe what to write — topic, key points, structure…'=>'Eleza kinachopaswa kuandikwa — mada, vidokezo muhimu, muundo…','Language (optional)'=>'Lugha (hiari)','— auto-detect —'=>'— kugundua kiotomatiki —','Generate'=>'Tengeneza','Clear hints'=>'Futa vidokezo','Clear All'=>'Futa Yote','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Boresha zaidi — mfano "fupisha" au "tumia sauti rasmi"…','Please enter some text first…'=>'Tafadhali ingiza maandishi kwanza…','Please enter some instructions first…'=>'Tafadhali ingiza maagizo kwanza…','Request failed. Please try again.'=>'Ombi limeshindwa. Tafadhali jaribu tena.','Tone:'=>'Sauti:','Language:'=>'Lugha:','Done'=>'Imekamilika','Lingua Forge AI Tools'=>'Vifaa vya Lingua Forge AI','Close popover'=>'Funga kidirisha','Paste text, or select text on the page first…'=>'Bandika maandishi, au chagua maandishi kwenye ukurasa kwanza…','Result will appear here…'=>'Matokeo yataonekana hapa…','Notice settings'=>'Mipangilio ya arifa','Notice message'=>'Ujumbe wa arifa','Shown when no translation exists for the visitor\'s language.'=>'Unaonyeshwa wakati hakuna tafsiri inayopo kwa lugha ya mgeni.','Show home link'=>'Onyesha kiungo cha nyumbani','Adds a link to the home page so visitors can browse in their language.'=>'Ongeza kiungo cha ukurasa wa nyumbani ili wageni waweze kuvinjari kwa lugha yao.','Home link text'=>'Maandishi ya kiungo cha nyumbani','block titleMissing Translation Notice'=>'Arifa ya Tafsiri Iliyokosewa','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Huonyesha arifa ya heshima wakati ukurasa wa sasa unaonyeshwa kwa lugha yake ya asili kwa sababu hakuna tafsiri inayopo kwa lugha ya mgeni. Inasababishwa na ishara ya LINGUAFORGE_LANG_FALLBACK_ACTIVE ya mtaalamu wa Lingua Forge — haitoi chochote wakati kuna tafsiri kwa eneo la ombi.','block keywordlanguage'=>'lugha','block keywordtranslation'=>'tafsiri','block keywordfallback'=>'kuzingatia','block keywordi18n'=>'i18n','block keywordlinguaforge'=>'linguaforge']];
